import { useEffect, useMemo, useState } from "react";
import { ArrowDown, ArrowLeft, ArrowUp, ArrowUpRight, BookOpen, ChevronDown, CirclePlay, ClipboardCheck, FileUp, GripVertical, Plus, Save, Trash2 } from "lucide-react";
import { Link, useSearchParams } from "react-router-dom";
import api from "../lib/api";
import { useFeedback } from "../context/FeedbackContext";
import { Spinner } from "../components/Loading";
import { useAuth } from "../context/AuthContext";

const inputClass = "field";

function DragHandle() {
  return <span className="inline-flex cursor-grab touch-none items-center text-zinc-400 active:cursor-grabbing" title="Seret untuk mengurutkan" aria-label="Seret untuk mengurutkan"><GripVertical size={18} /></span>;
}

async function reorderByDrag(items: any[], sourceId: string, targetId: string, move: (id: string, direction: "up" | "down") => Promise<void>) {
  const sourceIndex = items.findIndex((item: any) => item.id === sourceId);
  const targetIndex = items.findIndex((item: any) => item.id === targetId);
  if (sourceIndex < 0 || targetIndex < 0 || sourceIndex === targetIndex) return;
  const destination = sourceIndex < targetIndex ? targetIndex - 1 : targetIndex;
  let position = sourceIndex;
  while (position !== destination) {
    const direction = position > destination ? "up" : "down";
    await move(sourceId, direction);
    position += direction === "up" ? -1 : 1;
  }
}
const mediaUrl = (value: string) => value.startsWith("/") ? `${api.defaults.baseURL || ""}${value}` : value;
const toLocalDateTime = (value?: string | null) => value ? new Date(value).toISOString().slice(0, 16) : "";
const parseOptions = (value: unknown): string[] => { if (Array.isArray(value)) return value; try { const parsed = JSON.parse(String(value || "[]")); return Array.isArray(parsed) ? parsed : []; } catch { return []; } };
const newQuestion = () => ({ type: "MULTIPLE_CHOICE", text: "", options: ["", ""], correctIndex: 0, points: 10, imageUrl: "" });
const newAssignment = () => ({ title: "", description: "", isOpen: true, availableFrom: "", availableUntil: "", deadline: "" });
const newMaterial = () => ({ title: "", type: "VIDEO", sourceType: "youtube", sourceUrl: "", archived: false, isOpen: true, requireCompletionForDownload: false, availableFrom: "", availableUntil: "" });
const newQuiz = (title = "") => ({ title, kind: "QUIZ", passingScore: 60, timeLimit: "", timerMode: "INDEPENDENT", showAnswers: false, attemptLimited: true, attemptLimit: 1, isOpen: true, availableFrom: "", availableUntil: "", deadline: "", archived: false, resultReleaseMode: "AUTO", resultReleaseAt: "", randomizeQuestions: false, randomizeOptions: false, questionCount: null, questions: [newQuestion()] });

function SelectField({ value, onChange, options, label }: { value: string; onChange: (value: string) => void; options: { value: string; label: string }[]; label: string }) {
  return <label className="block space-y-2 text-sm font-medium">{label}<span className="select-shell"><select aria-label={label} value={value} onChange={(event) => onChange(event.target.value)} className="field select-field"><option value="" disabled>{label}</option>{options.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select><ChevronDown className="select-chevron" size={17} /></span></label>;
}

function CourseDetail({ course, user, lecturers, students, selectedLecturers, selectedStudents, setSelectedLecturers, setSelectedStudents, pickerReset, onBack, onModule, onEdit, onSaveLecturers, onSaveStudents, editing, form, setForm, save, cancel, startModule, editingModule, moduleTitle, setModuleTitle, saveModule, cancelModule, pending, onReorderModule, onReorderModuleTo, onDeleteModule, onCreateExam }: any) {
  const modules = [...(course.modules || [])].sort((a: any, b: any) => (a.order ?? 0) - (b.order ?? 0) || new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
  const hasType = (type: string) => modules.some((item: any) => item.type === type);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [dragOverId, setDragOverId] = useState<string | null>(null);
  const dropModule = async (event: any, targetId: string) => {
    event.preventDefault();
    const sourceId = event.dataTransfer.getData("text/plain") || draggingId;
    setDragOverId(null);
    if (!sourceId || sourceId === targetId) return;
    try {
      await onReorderModuleTo(sourceId, targetId);
    } finally {
      setDraggingId(null);
    }
  };
  return <div className="mx-auto max-w-6xl space-y-7"><Header eyebrow="Mata kuliah" title={course.title} back={onBack} backLabel="Kembali ke daftar mata kuliah" /><section className="section-card flex flex-wrap items-center gap-2"><button type="button" onClick={onEdit} className="secondary-button">Edit mata kuliah</button><button type="button" onClick={() => document.getElementById("course-settings")?.scrollIntoView({ behavior: "smooth" })} className="secondary-button">Kelola pengaturan</button></section>{editing && <CourseModal form={form} setForm={setForm} save={save} cancel={cancel} pending={pending} />}<div id="course-settings" className="space-y-5">{user?.role === "ADMIN" && <details open className="group section-card"><summary className="flex cursor-pointer list-none items-center justify-between font-semibold">Dosen pengampu<ChevronDown size={18} className="text-zinc-400 transition-transform group-open:rotate-180" /></summary><UserPicker role="DOSEN" selected={selectedLecturers} selectedUsers={lecturers} setSelected={setSelectedLecturers} resetSignal={pickerReset} /><button type="button" onClick={onSaveLecturers} className="secondary-button mt-3"><Save size={15} /> Simpan pengampu</button></details>}<details open className="group section-card"><summary className="flex cursor-pointer list-none items-center justify-between font-semibold">Mahasiswa terdaftar<ChevronDown size={18} className="text-zinc-400 transition-transform group-open:rotate-180" /></summary><UserPicker role="MAHASISWA" selected={selectedStudents} selectedUsers={students} setSelected={setSelectedStudents} resetSignal={pickerReset} /><button type="button" onClick={onSaveStudents} className="secondary-button mt-3"><Save size={15} /> Simpan peserta</button></details></div><section className="section-card space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="eyebrow">Course structure</p><h2 className="mt-1 font-semibold">Modul · {modules.length}</h2></div><div className="flex flex-wrap gap-2"><button type="button" onClick={startModule} className="primary-button"><Plus size={17} /> Tambah modul</button>{!hasType("UTS") && <button type="button" onClick={() => onCreateExam("UTS")} className="secondary-button">Tambah modul UTS</button>}{!hasType("UAS") && <button type="button" onClick={() => onCreateExam("UAS")} className="secondary-button">Tambah modul UAS</button>}</div></div>{editingModule && <div className="grid gap-3 rounded-xl border border-violet-200 p-4 dark:border-violet-900"><label className="block space-y-2 text-sm font-medium">Judul modul<input className={inputClass} value={moduleTitle} placeholder="Contoh: Pengantar materi" onChange={(event) => setModuleTitle(event.target.value)} /></label><FormButtons save={saveModule} cancel={cancelModule} pending={pending} /></div>}<p className="text-xs text-zinc-500">Seret ikon enam titik di kiri tombol naik untuk mengatur urutan modul.</p><div className="grid gap-4 md:grid-cols-2">{modules.map((item: any, index: number) => <article key={item.id} draggable onDragStart={(event) => { setDraggingId(item.id); event.dataTransfer.effectAllowed = "move"; event.dataTransfer.setData("text/plain", item.id); }} onDragOver={(event) => { event.preventDefault(); event.dataTransfer.dropEffect = "move"; setDragOverId(item.id); }} onDrop={(event) => { void dropModule(event, item.id); }} onDragEnd={() => { setDraggingId(null); setDragOverId(null); }} className={`rounded-2xl border border-zinc-200 p-5 transition dark:border-zinc-700 ${draggingId === item.id ? "opacity-50" : ""} ${dragOverId === item.id ? "ring-2 ring-violet-400" : ""}`}><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 flex-1 items-start gap-3"><button type="button" onClick={() => onModule(item.id)} className="min-w-0 flex-1 text-left"><span className="inline-flex rounded-lg bg-orange-100 px-2.5 py-1 text-xs font-bold text-orange-700">{item.type === "REGULAR" ? String(index + 1).padStart(2, "0") : item.type}</span><h3 className="mt-4 truncate font-semibold">{item.title}</h3><p className="mt-2 text-xs text-zinc-500">{item.assignments?.length || 0} tugas · {item.materials?.length || 0} materi · {item.quizzes?.length || 0} quiz</p></button></div><div className="flex shrink-0 items-center gap-1"><DragHandle /><button type="button" disabled={index === 0 || pending === "module-reorder"} onClick={() => onReorderModule(item.id, "up")} className="secondary-button min-h-8 px-2 py-1 text-xs disabled:opacity-40" title="Naikkan modul"><ArrowUp size={14} /></button><button type="button" disabled={index === modules.length - 1 || pending === "module-reorder"} onClick={() => onReorderModule(item.id, "down")} className="secondary-button min-h-8 px-2 py-1 text-xs disabled:opacity-40" title="Turunkan modul"><ArrowDown size={14} /></button></div></div><button type="button" onClick={() => onDeleteModule(item)} className="mt-4 text-xs font-semibold text-red-600 hover:underline">Hapus modul</button></article>)}</div>{modules.length === 0 && <p className="text-sm text-zinc-500">Belum ada modul pada mata kuliah ini.</p>}</section></div>;
}

function ModuleDetail({ course, module, onBack, editingAssignment, setEditingAssignment, assignment, setAssignment, saveAssignment, editingMaterial, setEditingMaterial, material, setMaterial, materialFile, setMaterialFile, saveMaterial, editingQuiz, setEditingQuiz, quiz, setQuiz, saveQuiz, uploadQuestionImage, pending, loadCourse, removeContent }: any) {
  const items = { assignments: module.assignments || [], materials: module.materials || [], quizzes: module.quizzes || [] };
  const reorder = (kind: string) => async (id: string, direction: string) => { try { await api.patch(`/api/${kind}/${id}/reorder`, { direction }); await loadCourse(); } catch { } };
  const reorderTo = (kind: string) => async (sourceId: string, targetId: string) => { try { await reorderByDrag((items as any)[kind] || [], sourceId, targetId, async (id, direction) => { await api.patch(`/api/${kind}/${id}/reorder`, { direction }); }); await loadCourse(); } catch { } };
  const editAssignment = (item: any) => { setEditingAssignment(item.id); setAssignment({ title: item.title, description: item.description || "", isOpen: item.isOpen !== false, availableFrom: toLocalDateTime(item.availableFrom), availableUntil: toLocalDateTime(item.availableUntil), deadline: toLocalDateTime(item.deadline) }); };
  const editMaterial = (item: any) => { setEditingMaterial(item.id); setMaterial({ ...newMaterial(), ...item, isOpen: item.isOpen !== false, availableFrom: toLocalDateTime(item.availableFrom), availableUntil: toLocalDateTime(item.availableUntil) }); setMaterialFile(null); };
  const editQuiz = (item: any) => { const limit = item.attemptLimit ?? 1; setEditingQuiz(item.id); setQuiz({ ...newQuiz(item.title), ...item, attemptLimited: limit !== -1, attemptLimit: limit < 0 ? 1 : limit, availableFrom: toLocalDateTime(item.availableFrom), availableUntil: toLocalDateTime(item.availableUntil), deadline: toLocalDateTime(item.deadline), resultReleaseAt: toLocalDateTime(item.resultReleaseAt), questions: (item.questions || []).map((question: any) => ({ ...question, options: parseOptions(question.options), imageUrl: question.imageUrl || "" })) }); };
  const archive = (kind: string) => async (item: any) => { try { await api.put(`/api/${kind}/${item.id}`, { archived: !item.archived }); await loadCourse(); } catch { } };
  return <div className="mx-auto max-w-6xl space-y-7"><div className="flex flex-wrap items-center gap-2 text-xs font-medium text-zinc-500"><button type="button" onClick={onBack} className="hover:text-violet-600">Kelola Mata Kuliah</button><span>→</span><span>{course.title}</span><span>→</span><span className="text-zinc-900 dark:text-zinc-100">{module.title}</span></div><Header eyebrow={`Modul · ${course.title}`} title={module.title} back={onBack} backLabel="Kembali ke detail mata kuliah" /><ContentOrderSection moduleId={module.id} assignments={items.assignments} materials={items.materials} quizzes={items.quizzes} loadCourse={loadCourse} /><ContentSection title="Tugas" icon={<ClipboardCheck size={18} />} items={items.assignments} start={() => { setEditingAssignment("new"); setAssignment(newAssignment()); }} reorder={reorder("assignments")} dragReorder={reorderTo("assignments")} renderItem={(item: any) => <><p className="font-semibold">{item.title}{item.archived && <span className="ml-2 text-xs text-zinc-400">(arsip)</span>}</p><Link to={`/assignment/${item.id}/submissions`} onClick={(event) => event.stopPropagation()} className="text-xs text-violet-700 underline">Nilai submission</Link><p className="text-xs text-zinc-500">{item.deadline ? `Deadline: ${new Date(item.deadline).toLocaleString()}` : "Tanpa deadline"}</p></>} edit={editAssignment} archive={archive("assignments")} remove={removeContent("assignments")} form={editingAssignment && <div className="grid gap-3"><label className="block space-y-2 text-sm font-medium">Judul tugas<input className={inputClass} placeholder="Contoh: Tugas rangkuman" value={assignment.title} onChange={(event) => setAssignment({ ...assignment, title: event.target.value })} /></label><label className="block space-y-2 text-sm font-medium">Instruksi tugas<textarea className={`${inputClass} min-h-24`} placeholder="Jelaskan tugas untuk mahasiswa" value={assignment.description} onChange={(event) => setAssignment({ ...assignment, description: event.target.value })} /></label><AvailabilityFields value={assignment} setValue={setAssignment} includeDeadline /><FormButtons save={saveAssignment} cancel={() => setEditingAssignment(null)} pending={pending} /></div>} /><ContentSection title="Materi" icon={<CirclePlay size={18} />} items={items.materials} start={() => { setEditingMaterial("new"); setMaterial(newMaterial()); setMaterialFile(null); }} reorder={reorder("materials")} dragReorder={reorderTo("materials")} renderItem={(item: any) => <><p className="font-semibold">{item.title}{item.archived && <span className="ml-2 text-xs text-zinc-400">(arsip)</span>}</p><p className="text-xs text-zinc-500">{item.type} · {item.sourceType}</p></>} edit={editMaterial} archive={archive("materials")} remove={removeContent("materials")} form={editingMaterial && <div className="grid gap-3 md:grid-cols-2"><label className="block space-y-2 text-sm font-medium">Judul materi<input className={inputClass} placeholder="Contoh: Video pengantar" value={material.title} onChange={(event) => setMaterial({ ...material, title: event.target.value })} /></label><SelectField value={material.type} onChange={(value) => setMaterial({ ...material, type: value })} label="Tipe materi" options={[{ value: "VIDEO", label: "Video" }, { value: "PDF", label: "PDF" }, { value: "PPT", label: "Presentasi" }]} /><SelectField value={material.sourceType} onChange={(value) => setMaterial({ ...material, sourceType: value })} label="Sumber materi" options={[{ value: "youtube", label: "YouTube" }, { value: "drive", label: "Google Drive" }, { value: "upload", label: "Upload file" }]} /><label className="block space-y-2 text-sm font-medium">URL sumber<input className={inputClass} placeholder="https://..." value={material.sourceUrl} onChange={(event) => setMaterial({ ...material, sourceUrl: event.target.value })} /></label>{material.sourceType === "upload" && <label className="block space-y-2 text-sm font-medium">File bahan ajar<input type="file" className="field p-2" accept=".pdf,.ppt,.pptx,.mp4,.webm,.mov" onChange={(event) => setMaterialFile(event.target.files?.[0] || null)} /></label>}<div className="col-span-full rounded-lg bg-violet-50 px-3 py-2 text-xs text-violet-800 dark:bg-violet-950/30 dark:text-violet-200">Durasi video dan jumlah halaman diambil otomatis dari pemutar atau file materi.</div><div className="col-span-full"><AvailabilityFields value={material} setValue={setMaterial} /></div><label className="col-span-full flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={Boolean(material.requireCompletionForDownload)} onChange={(event) => setMaterial({ ...material, requireCompletionForDownload: event.target.checked })} /> Wajib selesai membaca/menonton sebelum download</label><FormButtons save={saveMaterial} cancel={() => setEditingMaterial(null)} pending={pending} /></div>} /><ContentSection title="Quiz" icon={<ClipboardCheck size={18} />} items={items.quizzes} start={() => { setEditingQuiz("new"); setQuiz(newQuiz()); }} reorder={reorder("quizzes")} dragReorder={reorderTo("quizzes")} renderItem={(item: any) => <><p className="font-semibold">{item.title}{item.archived && <span className="ml-2 text-xs text-zinc-400">(arsip)</span>}</p><p className="text-xs text-zinc-500">{item.kind} · {item.questions?.length || 0} soal · {item.deadline ? `Deadline: ${new Date(item.deadline).toLocaleString()}` : "Tanpa deadline"}</p></>} edit={editQuiz} archive={archive("quizzes")} remove={removeContent("quizzes")} form={editingQuiz && <QuizForm quiz={quiz} setQuiz={setQuiz} save={saveQuiz} cancel={() => setEditingQuiz(null)} uploadQuestionImage={uploadQuestionImage} pending={pending} />} /></div>;
}

function FormButtons({ save, cancel, pending }: { save: () => void | Promise<void>; cancel: () => void; pending: string | null }) {
  const handleSave = async () => {
    if (pending !== null) return;
    await save();
  };
  return <div className="flex flex-wrap justify-end gap-2"><button type="button" onClick={cancel} disabled={pending !== null} className="secondary-button">Batal</button><button type="button" onClick={handleSave} disabled={pending !== null} aria-busy={pending !== null} className="primary-button">{pending ? <><Spinner /> Menyimpan...</> : <><Save size={16} /> Simpan</>}</button></div>;
}

function UserPicker({ role, selected, selectedUsers, setSelected, resetSignal = 0 }: { role: "DOSEN" | "MAHASISWA"; selected: string[]; selectedUsers: any[]; setSelected: (value: (current: string[]) => string[]) => void; resetSignal?: number }) {
  const [open, setOpen] = useState(false); const [search, setSearch] = useState(""); const [page, setPage] = useState(1); const [results, setResults] = useState<any[]>([]); const [total, setTotal] = useState(0); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const limit = 25;
  useEffect(() => { setOpen(false); setSearch(""); setPage(1); }, [resetSignal]);
  useEffect(() => { if (!open) return; const timer = window.setTimeout(() => { setLoading(true); api.get("/api/auth/users", { params: { role, search, page, limit } }).then((response) => { const items = Array.isArray(response.data) ? response.data : response.data?.items || []; setResults(items); setTotal(Array.isArray(response.data) ? items.length : response.data?.total || 0); setError(""); }).catch(() => { setResults([]); setTotal(0); setError("Daftar pengguna tidak dapat dimuat."); }).finally(() => setLoading(false)); }, 280); return () => window.clearTimeout(timer); }, [open, role, search, page]);
  const chosen = [...selectedUsers, ...results].filter((item, index, list) => selected.includes(item.id) && list.findIndex((candidate) => candidate.id === item.id) === index); const toggle = (id: string) => setSelected((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]); const totalPages = Math.max(1, Math.ceil(total / limit));
  return <div className="mt-4 space-y-3"><p className="text-sm text-zinc-500">{selected.length} {role === "MAHASISWA" ? "mahasiswa" : "dosen"} dipilih.</p>{chosen.length > 0 && <div className="flex flex-wrap gap-2">{chosen.slice(0, 5).map((item) => <button type="button" key={item.id} onClick={() => toggle(item.id)} className="rounded-full bg-violet-100 px-3 py-1 text-xs text-violet-800">{item.name} ({item.nim}) ×</button>)}{chosen.length > 5 && <span className="rounded-full bg-zinc-100 px-3 py-1 text-xs text-zinc-600">+{chosen.length - 5} pilihan lain</span>}</div>}{open ? <><label className="block space-y-2 text-sm font-medium">Cari nama atau NIM/NIDN<input className={inputClass} placeholder="Ketik nama atau identifier pengguna" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} /></label>{loading && <p className="text-xs text-zinc-500">Memuat hasil pengguna...</p>}{error && <p role="alert" className="text-xs text-red-600">{error}</p>}{!loading && !error && <div className="grid max-h-72 gap-2 overflow-y-auto sm:grid-cols-2">{results.filter((item) => !selected.includes(item.id)).map((item) => <label key={item.id} className="flex gap-2 rounded-lg bg-zinc-50 p-2 text-sm dark:bg-zinc-800"><input type="checkbox" checked={false} onChange={() => toggle(item.id)} />{item.name} ({item.nim})</label>)}{results.filter((item) => !selected.includes(item.id)).length === 0 && <p className="text-xs text-zinc-500">Tidak ada hasil pada halaman ini.</p>}</div>}{total > 0 && <div className="flex flex-wrap items-center gap-2 text-xs text-zinc-500"><button type="button" disabled={page <= 1 || loading} onClick={() => setPage((value) => value - 1)} className="secondary-button min-h-8 px-2 py-1 disabled:opacity-40">Sebelumnya</button><span>Halaman {page} dari {totalPages} · {total} hasil</span><button type="button" disabled={page >= totalPages || loading} onClick={() => setPage((value) => value + 1)} className="secondary-button min-h-8 px-2 py-1 disabled:opacity-40">Berikutnya</button></div>}</> : <button type="button" onClick={() => setOpen(true)} className="secondary-button">Kelola pilihan</button>}</div>;
}

export default function Manage() {
  const { user } = useAuth(); const { showFeedback, requestConfirmation, setUnsavedChanges } = useFeedback(); const [params, setParams] = useSearchParams(); const courseId = params.get("courseId") || ""; const moduleId = params.get("moduleId") || "";
  const [courses, setCourses] = useState<any[]>([]); const [course, setCourse] = useState<any>(null); const [error, setError] = useState(""); const [pending, setPending] = useState<string | null>(null); const [lecturers, setLecturers] = useState<any[]>([]); const [students, setStudents] = useState<any[]>([]); const [selectedLecturers, setSelectedLecturers] = useState<string[]>([]); const [selectedStudents, setSelectedStudents] = useState<string[]>([]); const [pickerReset, setPickerReset] = useState(0); const [editingCourse, setEditingCourse] = useState(false); const [courseForm, setCourseForm] = useState({ title: "", description: "" }); const [editingModule, setEditingModule] = useState<string | null>(null); const [moduleTitle, setModuleTitle] = useState(""); const [editingAssignment, setEditingAssignment] = useState<string | null>(null); const [assignment, setAssignment] = useState(newAssignment()); const [editingMaterial, setEditingMaterial] = useState<string | null>(null); const [material, setMaterial] = useState(newMaterial()); const [materialFile, setMaterialFile] = useState<File | null>(null); const [editingQuiz, setEditingQuiz] = useState<string | null>(null); const [quiz, setQuiz] = useState<any>(newQuiz());
  const loadCourses = async () => { try { const response = await api.get("/api/courses"); setCourses(Array.isArray(response.data) ? response.data : []); setError(""); } catch { setError("Daftar mata kuliah belum dapat dimuat."); } };
  const loadCourse = async (id: string) => { try { const response = await api.get(`/api/courses/${id}`); setCourse(response.data); setLecturers((response.data.instructors || []).map((item: any) => item.user || item).filter((item: any) => item.id)); setSelectedLecturers((response.data.instructors || []).map((item: any) => item.user?.id || item.userId || item.id)); const enrollments = await api.get(`/api/courses/${id}/enrollments`); setStudents((enrollments.data || []).map((item: any) => item.user || item).filter((item: any) => item.id)); setSelectedStudents((enrollments.data || []).map((item: any) => item.user?.id || item.userId).filter(Boolean)); setError(""); } catch (reason: any) { setCourse(null); setError(reason?.response?.data?.message || "Detail mata kuliah belum dapat dimuat."); } };
  useEffect(() => { loadCourses(); }, []); useEffect(() => { if (courseId) loadCourse(courseId); else setCourse(null); }, [courseId]); useEffect(() => { const dirty = editingCourse || Boolean(editingModule || editingAssignment || editingMaterial || editingQuiz); setUnsavedChanges(dirty ? "Perubahan belum disimpan." : null); return () => setUnsavedChanges(null); }, [editingCourse, editingModule, editingAssignment, editingMaterial, editingQuiz, setUnsavedChanges]);
  const module = useMemo(() => course?.modules?.find((item: any) => item.id === moduleId) || null, [course, moduleId]); useEffect(() => { if (moduleId && course && !module) setParams({ courseId }); }, [moduleId, course, module]); const resetForms = () => { setEditingCourse(false); setEditingModule(null); setEditingAssignment(null); setEditingMaterial(null); setEditingQuiz(null); setMaterialFile(null); };
  const saveCourse = async () => { setPending("course"); try { if (course && editingCourse) await api.put(`/api/courses/${course.id}`, courseForm); else { const response = await api.post("/api/courses", courseForm); await loadCourses(); setParams({ courseId: response.data.id }); } setEditingCourse(false); await loadCourses(); if (course) await loadCourse(course.id); showFeedback("Mata kuliah berhasil disimpan."); } catch (reason: any) { showFeedback(reason?.response?.data?.message || "Mata kuliah gagal disimpan.", "error"); } finally { setPending(null); } };
  const saveModule = async () => { if (!course) return; setPending("module"); try { if (editingModule && editingModule !== "new") await api.put(`/api/courses/modules/${editingModule}`, { title: moduleTitle }); else await api.post(`/api/courses/${course.id}/modules`, { title: moduleTitle, type: "REGULAR", order: course.modules.length + 1 }); setEditingModule(null); setModuleTitle(""); await loadCourse(course.id); showFeedback("Modul berhasil disimpan."); } catch (reason: any) { showFeedback(reason?.response?.data?.message || "Modul gagal disimpan.", "error"); } finally { setPending(null); } };
  const createExamModule = async (type: "UTS" | "UAS") => { if (!course) return; setPending("module"); try { await api.post(`/api/courses/${course.id}/modules`, { title: type, type, order: course.modules.length + 1 }); await loadCourse(course.id); showFeedback(`${type} berhasil dibuat.`); } catch (reason: any) { showFeedback(reason?.response?.data?.message || `${type} gagal dibuat.`, "error"); } finally { setPending(null); } };
  const saveAssignment = async () => {
    if (!course || !module) {
      showFeedback("Modul tugas belum siap dimuat. Buka ulang modul lalu coba lagi.", "error");
      return;
    }
    if (assignment.title.trim().length < 2) {
      showFeedback("Judul tugas minimal 2 karakter.", "error");
      return;
    }
    const toIso = (value: string, label: string) => {
      if (!value) return null;
      const date = new Date(value);
      if (Number.isNaN(date.getTime())) throw new Error(`${label} tidak valid.`);
      return date.toISOString();
    };
    try {
      const availableFrom = toIso(assignment.availableFrom, "Jadwal mulai tersedia");
      const availableUntil = toIso(assignment.availableUntil, "Jadwal akses berakhir");
      const deadline = toIso(assignment.deadline, "Deadline tugas");
      if (availableFrom && availableUntil && new Date(availableFrom) > new Date(availableUntil)) throw new Error("Jadwal mulai tersedia harus sebelum jadwal akses berakhir.");
      if (availableFrom && deadline && new Date(availableFrom) > new Date(deadline)) throw new Error("Jadwal mulai tersedia harus sebelum deadline tugas.");
      if (availableUntil && deadline && new Date(deadline) > new Date(availableUntil)) throw new Error("Deadline tugas harus sebelum atau sama dengan jadwal akses berakhir.");
      setPending("assignment");
      const data = { courseId: course.id, moduleId: module.id, title: assignment.title.trim(), description: assignment.description, isOpen: assignment.isOpen, availableFrom, availableUntil, deadline };
      if (editingAssignment === "new") await api.post("/api/assignments", data); else await api.put(`/api/assignments/${editingAssignment}`, data);
      setEditingAssignment(null);
      setAssignment(newAssignment());
      await loadCourse(course.id);
      showFeedback("Tugas berhasil disimpan.");
    } catch (reason: any) {
      const detail = reason?.response?.data?.message || reason?.response?.data?.issues?.map((item: any) => item.message).join(" ") || reason?.message;
      showFeedback(detail || "Tugas gagal disimpan. Periksa judul, modul, dan jadwal tugas.", "error");
    } finally {
      setPending(null);
    }
  };
  const saveMaterial = async () => { if (!course || !module) { showFeedback("Modul materi belum siap dimuat. Buka ulang modul lalu coba lagi.", "error"); return; } setPending("material"); try { const base: any = { moduleId: module.id, title: material.title, type: material.type, sourceType: material.sourceType, sourceUrl: material.sourceUrl, archived: material.archived, isOpen: material.isOpen, requireCompletionForDownload: material.requireCompletionForDownload, availableFrom: material.availableFrom ? new Date(material.availableFrom).toISOString() : null, availableUntil: material.availableUntil ? new Date(material.availableUntil).toISOString() : null }; if (materialFile) { const form = new FormData(); Object.entries(base).forEach(([key, value]) => form.append(key, String(value ?? ""))); form.append("file", materialFile); if (editingMaterial === "new") await api.post("/api/materials/upload", form); else await api.put(`/api/materials/${editingMaterial}/upload`, form); } else { if (material.sourceType === "upload" && !material.sourceUrl) throw new Error("Pilih file materi atau isi sumber file yang sudah ada."); if (editingMaterial === "new") await api.post("/api/materials", base); else await api.put(`/api/materials/${editingMaterial}`, base); } setEditingMaterial(null); setMaterial(newMaterial()); setMaterialFile(null); await loadCourse(course.id); showFeedback("Materi berhasil disimpan."); } catch (reason: any) { showFeedback(reason?.response?.data?.message || reason?.message || "Materi gagal disimpan.", "error"); } finally { setPending(null); } };
  const saveQuiz = async () => { if (!course || !module) return; setPending("quiz"); try { const data = { courseId: course.id, moduleId: module.id, ...quiz, kind: module.type === "UTS" || module.type === "UAS" ? "QUIZ" : quiz.kind, timerMode: quiz.timerMode || "INDEPENDENT", attemptLimit: quiz.attemptLimited ? Number(quiz.attemptLimit) : -1, isOpen: quiz.isOpen !== false, availableFrom: quiz.availableFrom ? new Date(quiz.availableFrom).toISOString() : null, availableUntil: quiz.availableUntil ? new Date(quiz.availableUntil).toISOString() : null, deadline: quiz.deadline ? new Date(quiz.deadline).toISOString() : null, resultReleaseAt: quiz.resultReleaseAt ? new Date(quiz.resultReleaseAt).toISOString() : null, timeLimit: quiz.timeLimit ? Number(quiz.timeLimit) : null, questionCount: quiz.questionCount ? Number(quiz.questionCount) : null, questions: quiz.questions.map((item: any, index: number) => ({ ...item, points: Number(item.points || 10), order: index + 1, options: item.type === "ESSAY" ? [] : item.options, correctIndex: item.type === "ESSAY" ? null : Number(item.correctIndex), imageUrl: item.imageUrl || null })) }; if (editingQuiz === "new") await api.post("/api/quizzes", data); else { await api.put(`/api/quizzes/${editingQuiz}`, data); if (quiz.resultReleaseMode === "AUTO") await api.patch(`/api/quizzes/${editingQuiz}/result-release-auto`); } setEditingQuiz(null); await loadCourse(course.id); showFeedback("Quiz berhasil disimpan."); } catch (reason: any) { showFeedback(reason?.response?.data?.message || "Quiz gagal disimpan. Periksa pertanyaan, opsi, jadwal, dan publikasi nilai.", "error"); } finally { setPending(null); } };
  const uploadQuestionImage = async (index: number, file: File) => { const form = new FormData(); form.append("file", file); try { const response = await api.post("/api/quizzes/upload-image", form); const questions = [...quiz.questions]; questions[index] = { ...questions[index], imageUrl: response.data.imageUrl }; setQuiz({ ...quiz, questions }); showFeedback("Gambar soal berhasil diunggah."); } catch (reason: any) { showFeedback(reason?.response?.data?.message || "Gambar soal gagal diunggah.", "error"); } };
  const reorderModule = async (id: string, direction: string) => { setPending("module-reorder"); try { await api.patch(`/api/courses/modules/${id}/reorder`, { direction }); await loadCourse(course.id); } catch (reason: any) { showFeedback(reason?.response?.data?.message || "Urutan modul gagal diubah.", "error"); } finally { setPending(null); } };
  const reorderModuleTo = async (sourceId: string, targetId: string) => { setPending("module-reorder"); try { const modules = [...(course?.modules || [])].sort((a: any, b: any) => (a.order ?? 0) - (b.order ?? 0) || new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()); await reorderByDrag(modules, sourceId, targetId, async (id, direction) => { await api.patch(`/api/courses/modules/${id}/reorder`, { direction }); }); await loadCourse(course.id); } catch (reason: any) { showFeedback(reason?.response?.data?.message || "Urutan modul gagal diubah.", "error"); } finally { setPending(null); } };
  const deleteModule = async (item: any) => { if (!(await requestConfirmation(`Hapus modul ${item.title} beserta seluruh isinya?`))) return; try { await api.delete(`/api/courses/modules/${item.id}`); if (moduleId === item.id) setParams({ courseId }); await loadCourse(course.id); showFeedback("Modul berhasil dihapus."); } catch (reason: any) { showFeedback(reason?.response?.data?.message || "Modul gagal dihapus.", "error"); } };
  const removeContent = (kind: "assignments" | "materials" | "quizzes") => async (item: any) => { const labels = { assignments: "tugas", materials: "materi", quizzes: "quiz" }; if (!(await requestConfirmation(`Hapus ${labels[kind]} ${item.title}? Data dan lampiran terkait akan dihapus.`))) return; setPending(`${kind}-delete`); try { await api.delete(`/api/${kind}/${item.id}`); await loadCourse(course.id); showFeedback(`${labels[kind][0].toUpperCase()}${labels[kind].slice(1)} berhasil dihapus.`); } catch (reason: any) { showFeedback(reason?.response?.data?.message || `${labels[kind]} gagal dihapus.`, "error"); } finally { setPending(null); } };
 if (!courseId) return <CourseList courses={courses} error={error} onSelect={(id: string) => setParams({ courseId: id })} onCreate={() => { resetForms(); setEditingCourse(true); }} canCreate={user?.role === "ADMIN"} editing={editingCourse} form={courseForm} setForm={setCourseForm} save={saveCourse} cancel={resetForms} pending={pending} />; if (!course) return <div className="mx-auto max-w-6xl section-card" role="alert">{error || "Memuat mata kuliah..."}</div>; if (!moduleId || !module) return <CourseDetail course={course} user={user} lecturers={lecturers} students={students} selectedLecturers={selectedLecturers} selectedStudents={selectedStudents} pickerReset={pickerReset} setSelectedLecturers={setSelectedLecturers} setSelectedStudents={setSelectedStudents} onBack={() => setParams({})} onModule={(id: string) => setParams({ courseId, moduleId: id })} onEdit={() => { setCourseForm({ title: course.title, description: course.description || "" }); setEditingCourse(true); }} onSaveLecturers={async () => { try { await api.put(`/api/courses/${course.id}/instructors`, { userIds: selectedLecturers }); await loadCourse(course.id); setPickerReset((value) => value + 1); showFeedback("Dosen pengampu diperbarui."); } catch (reason: any) { showFeedback(reason?.response?.data?.message || "Pengaturan dosen gagal disimpan.", "error"); } }} onSaveStudents={async () => { try { await api.put(`/api/courses/${course.id}/enrollments`, { userIds: selectedStudents }); await loadCourse(course.id); setPickerReset((value) => value + 1); showFeedback("Peserta diperbarui."); } catch (reason: any) { showFeedback(reason?.response?.data?.message || "Pengaturan peserta gagal disimpan.", "error"); } }} editing={editingCourse} form={courseForm} setForm={setCourseForm} save={saveCourse} cancel={resetForms} startModule={() => { setEditingModule("new"); setModuleTitle(""); }} editingModule={editingModule} moduleTitle={moduleTitle} setModuleTitle={setModuleTitle} saveModule={saveModule} cancelModule={() => setEditingModule(null)} pending={pending} onReorderModule={reorderModule} onReorderModuleTo={reorderModuleTo} onDeleteModule={deleteModule} onCreateExam={createExamModule} />; if (module.type === "UTS" || module.type === "UAS") return <ExamModuleDetail course={course} module={module} onBack={() => setParams({ courseId })} editingQuiz={editingQuiz} setEditingQuiz={setEditingQuiz} quiz={quiz} setQuiz={setQuiz} saveQuiz={saveQuiz} uploadQuestionImage={uploadQuestionImage} pending={pending} loadCourse={() => loadCourse(course.id)} removeContent={removeContent} />; return <ModuleDetail course={course} module={module} onBack={() => setParams({ courseId })} editingAssignment={editingAssignment} setEditingAssignment={setEditingAssignment} assignment={assignment} setAssignment={setAssignment} saveAssignment={saveAssignment} editingMaterial={editingMaterial} setEditingMaterial={setEditingMaterial} material={material} setMaterial={setMaterial} materialFile={materialFile} setMaterialFile={setMaterialFile} saveMaterial={saveMaterial} editingQuiz={editingQuiz} setEditingQuiz={setEditingQuiz} quiz={quiz} setQuiz={setQuiz} saveQuiz={saveQuiz} uploadQuestionImage={uploadQuestionImage} pending={pending} loadCourse={() => loadCourse(course.id)} removeContent={removeContent} />;
}

function CourseList({ courses, error, onSelect, onCreate, canCreate, editing, form, setForm, save, cancel, pending }: any) { return <div className="mx-auto max-w-6xl space-y-7"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="eyebrow">Content studio</p><h1 className="mt-2 text-3xl font-bold">Kelola mata kuliah</h1><p className="mt-2 text-sm text-zinc-500">Pilih kartu mata kuliah untuk membuka ruang kelolanya.</p></div>{canCreate && <button type="button" onClick={onCreate} className="primary-button"><Plus size={17} /> Tambah mata kuliah</button>}</div>{error && <div role="alert" className="section-card text-sm text-amber-700">{error}</div>}{editing && <CourseModal form={form} setForm={setForm} save={save} cancel={cancel} pending={pending} />}{courses.length > 0 ? <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{courses.map((item: any) => <button type="button" key={item.id} onClick={() => onSelect(item.id)} className="group section-card text-left transition hover:-translate-y-1 hover:shadow-xl"><div className="flex items-start justify-between"><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-violet-100 text-violet-700"><BookOpen size={19} /></span><ArrowUpRight size={18} className="text-zinc-300 group-hover:text-violet-600" /></div><h2 className="mt-5 font-semibold">{item.title}</h2><p className="mt-2 line-clamp-2 text-sm text-zinc-500">{item.description || "Mata kuliah pembelajaran."}</p><p className="mt-5 text-xs font-medium text-zinc-500">{item.moduleCount || 0} modul · {(item.materialCount || 0) + (item.assignmentCount || 0) + (item.quizCount || 0)} aktivitas</p></button>)}</div> : <div className="section-card text-sm text-zinc-500">Belum ada mata kuliah yang dapat dikelola.</div>}</div>; }
function CourseModal({ form, setForm, save, cancel, pending }: any) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4" role="dialog" aria-modal="true" aria-labelledby="course-modal-title"><div className="section-card w-full max-w-xl space-y-4" onMouseDown={(event) => event.stopPropagation()}><h2 id="course-modal-title" className="text-lg font-semibold">Mata kuliah</h2><label className="block space-y-2 text-sm font-medium">Nama mata kuliah<input className={inputClass} value={form.title} placeholder="Contoh: Pengantar Pemrograman" onChange={(event) => setForm({ ...form, title: event.target.value })} /></label><label className="block space-y-2 text-sm font-medium">Deskripsi<textarea className={`${inputClass} min-h-24`} value={form.description} placeholder="Ringkasan mata kuliah" onChange={(event) => setForm({ ...form, description: event.target.value })} /></label><FormButtons save={save} cancel={cancel} pending={pending} /></div></div>; }
function Header({ eyebrow, title, back, backLabel }: { eyebrow: string; title: string; back: () => void; backLabel: string }) { return <div className="flex items-center gap-3"><button type="button" onClick={back} className="secondary-button min-h-10 px-3" aria-label={backLabel}><ArrowLeft size={17} /></button><div><p className="eyebrow">{eyebrow}</p><h1 className="mt-1 text-2xl font-bold tracking-tight sm:text-3xl">{title}</h1></div></div>; }
function AvailabilityFields({ value, setValue, includeDeadline = false }: any) { const from = value.availableFrom || ""; const until = value.availableUntil || ""; return <div className="grid gap-3 rounded-xl border border-zinc-200 p-4 dark:border-zinc-700 md:grid-cols-2"><label className="col-span-full flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={value.isOpen !== false} onChange={(event) => setValue({ ...value, isOpen: event.target.checked })} /> Buka untuk mahasiswa</label><p className="col-span-full text-xs text-zinc-500">Jika ditutup, mahasiswa hanya melihat preview aman dan tidak dapat membuka, mencatat progress, mengunduh, atau mengirim jawaban.</p><label className="block space-y-2 text-sm font-medium">Jadwal mulai tersedia<input type="datetime-local" className={inputClass} value={from} max={until || undefined} onChange={(event) => setValue({ ...value, availableFrom: event.target.value })} /><span className="block text-xs font-normal text-zinc-500">Kosong = langsung tersedia.</span></label><label className="block space-y-2 text-sm font-medium">Jadwal akses berakhir<input type="datetime-local" className={inputClass} value={until} min={from || undefined} max={includeDeadline && value.deadline ? value.deadline : undefined} onChange={(event) => setValue({ ...value, availableUntil: event.target.value })} /><span className="block text-xs font-normal text-zinc-500">Kosong = terus terbuka.</span></label>{includeDeadline && <label className="block space-y-2 text-sm font-medium">Deadline pengumpulan/pengerjaan<input type="datetime-local" className={inputClass} value={value.deadline || ""} min={from || undefined} max={until || undefined} onChange={(event) => setValue({ ...value, deadline: event.target.value })} /><span className="block text-xs font-normal text-zinc-500">Kosong = tidak ada batas aksi.</span></label>}</div>; }


function ContentOrderSection({ moduleId, assignments, materials, quizzes, loadCourse }: any) {
  const items = [...assignments.map((item: any) => ({ ...item, itemType: "assignment", label: "Tugas" })), ...materials.map((item: any) => ({ ...item, itemType: "material", label: "Materi" })), ...quizzes.map((item: any) => ({ ...item, itemType: "quiz", label: "Quiz" }))].sort((a: any, b: any) => (a.contentOrder ?? 0) - (b.contentOrder ?? 0) || new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [dragOverId, setDragOverId] = useState<string | null>(null);
  const reorder = async (item: any, direction: string) => { try { await api.patch(`/api/courses/modules/${moduleId}/content/reorder`, { itemType: item.itemType, itemId: item.id, direction }); await loadCourse(); } catch { } };
  const reorderTo = async (sourceId: string, targetId: string) => { try { await reorderByDrag(items, sourceId, targetId, async (id, direction) => { const source = items.find((item: any) => item.id === id); if (source) await api.patch(`/api/courses/modules/${moduleId}/content/reorder`, { itemType: source.itemType, itemId: source.id, direction }); }); await loadCourse(); } catch { } };
  const drop = async (event: any, target: any) => { event.preventDefault(); const sourceKey = event.dataTransfer.getData("text/plain") || draggingId; setDragOverId(null); if (!sourceKey) return; const sourceId = sourceKey.includes(":") ? sourceKey.slice(sourceKey.indexOf(":") + 1) : sourceKey; if (sourceId === target.id) return; try { await reorderTo(sourceId, target.id); } finally { setDraggingId(null); } };
  return <details className="group section-card space-y-4"><summary className="flex cursor-pointer list-none items-center justify-between font-semibold">Urutan konten modul<ChevronDown size={18} className="text-zinc-400 transition-transform group-open:rotate-180" /></summary><p className="text-sm text-zinc-500">Susun alur materi, tugas, dan quiz tanpa membuat ulang item. Seret ikon enam titik di kiri tombol naik.</p><div className="max-h-[32rem] space-y-2 overflow-y-auto">{items.map((item: any, index: number) => { const key = `${item.itemType}:${item.id}`; return <div key={key} draggable onDragStart={(event) => { setDraggingId(key); event.dataTransfer.effectAllowed = "move"; event.dataTransfer.setData("text/plain", key); }} onDragOver={(event) => { event.preventDefault(); event.dataTransfer.dropEffect = "move"; setDragOverId(key); }} onDrop={(event) => { void drop(event, item); }} onDragEnd={() => { setDraggingId(null); setDragOverId(null); }} className={`flex flex-wrap items-center justify-between gap-3 rounded-xl bg-zinc-50 px-3 py-3 text-sm transition dark:bg-zinc-800/70 ${draggingId === key ? "opacity-50" : ""} ${dragOverId === key ? "ring-2 ring-violet-400" : ""}`}><div className="flex min-w-0 flex-1 items-start gap-3"><div><p className="font-semibold">{index + 1}. {item.title}</p><p className="text-xs text-zinc-500">{item.label}{item.deadline ? ` · Deadline ${new Date(item.deadline).toLocaleString()}` : ""}</p></div></div><div className="flex items-center gap-2"><DragHandle /><button type="button" disabled={index === 0} onClick={() => reorder(item, "up")} className="secondary-button min-h-9 px-2 py-1.5 text-xs disabled:opacity-40" title="Naikkan"><ArrowUp size={14} /></button><button type="button" disabled={index === items.length - 1} onClick={() => reorder(item, "down")} className="secondary-button min-h-9 px-2 py-1.5 text-xs disabled:opacity-40" title="Turunkan"><ArrowDown size={14} /></button></div></div>; })}</div>{items.length === 0 && <p className="text-sm text-zinc-500">Belum ada konten.</p>}</details>;
}

function ContentSection({ title, icon, items, start, renderItem, edit, archive, remove, form, reorder, dragReorder }: any) {
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("ALL");
  const [page, setPage] = useState(1);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [dragOverId, setDragOverId] = useState<string | null>(null);
  const limit = 25;
  const filtered = items.filter((item: any) => status === "ALL" || status === "ARCHIVED" ? status === "ALL" ? true : item.archived : !item.archived).filter((item: any) => item.title.toLowerCase().includes(search.toLowerCase()));
  const totalPages = Math.max(1, Math.ceil(filtered.length / limit));
  const visible = filtered.slice((page - 1) * limit, page * limit);
  const indexOf = (id: string) => items.findIndex((item: any) => item.id === id);
  const publish = async (item: any) => { await api.patch(`/api/quizzes/${item.id}/result-release`, { resultReleaseMode: "MANUAL", publish: true }); window.location.reload(); };
  const drop = async (event: any, targetId: string) => { event.preventDefault(); const sourceId = event.dataTransfer.getData("text/plain") || draggingId; setDragOverId(null); if (!sourceId || sourceId === targetId || !dragReorder) return; try { await dragReorder(sourceId, targetId); } finally { setDraggingId(null); } };
  return <details open className="group section-card space-y-4"><summary className="flex cursor-pointer list-none items-center justify-between"><span className="flex items-center gap-3 font-semibold"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-violet-100 text-violet-700">{icon}</span>{title} · {filtered.length}</span><ChevronDown size={18} className="text-zinc-400 transition-transform group-open:rotate-180" /></summary><div className="grid gap-3 md:grid-cols-[1fr_12rem]"><label className="block space-y-2 text-sm font-medium">Cari {title.toLowerCase()}<input className={inputClass} placeholder={`Cari judul ${title.toLowerCase()}`} value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} /></label><SelectField value={status} onChange={(value) => { setStatus(value); setPage(1); }} label="Status item" options={[{ value: "ACTIVE", label: "Aktif" }, { value: "ARCHIVED", label: "Arsip" }, { value: "ALL", label: "Semua" }]} /></div><button type="button" onClick={start} className="primary-button"><Plus size={17} /> Tambah {title.toLowerCase()}</button>{form}{dragReorder && <p className="text-xs text-zinc-500">Seret ikon enam titik di kiri tombol naik untuk mengurutkan.</p>}<div className="space-y-2">{visible.map((item: any) => { const globalIndex = indexOf(item.id); return <div key={item.id} draggable={Boolean(dragReorder)} onDragStart={(event) => { if (!dragReorder) return; setDraggingId(item.id); event.dataTransfer.effectAllowed = "move"; event.dataTransfer.setData("text/plain", item.id); }} onDragOver={(event) => { if (!dragReorder) return; event.preventDefault(); event.dataTransfer.dropEffect = "move"; setDragOverId(item.id); }} onDrop={(event) => { void drop(event, item.id); }} onDragEnd={() => { setDraggingId(null); setDragOverId(null); }} className={`flex flex-wrap items-center justify-between gap-3 rounded-xl bg-zinc-50 px-3 py-3 text-sm transition dark:bg-zinc-800/70 ${draggingId === item.id ? "opacity-50" : ""} ${dragOverId === item.id ? "ring-2 ring-violet-400" : ""}`}><div className="flex min-w-0 flex-1 items-start gap-3"><div className="min-w-0 flex-1">{renderItem(item)}</div></div><div className="flex flex-wrap items-center gap-2">{dragReorder && <DragHandle />}<button type="button" disabled={globalIndex === 0} onClick={() => reorder?.(item.id, "up")} className="secondary-button min-h-9 px-2 py-1.5 text-xs disabled:opacity-40" title="Naikkan"><ArrowUp size={14} /></button><button type="button" disabled={globalIndex === items.length - 1} onClick={() => reorder?.(item.id, "down")} className="secondary-button min-h-9 px-2 py-1.5 text-xs disabled:opacity-40" title="Turunkan"><ArrowDown size={14} /></button>{title === "Quiz" && item.resultReleaseMode === "MANUAL" && !item.resultPublishedAt && <button type="button" onClick={() => publish(item)} className="secondary-button min-h-9 px-3 py-1.5 text-xs">Publikasikan hasil</button>}<button type="button" onClick={() => edit(item)} className="secondary-button min-h-9 px-3 py-1.5 text-xs">Edit</button><button type="button" onClick={() => archive(item)} className="secondary-button min-h-9 px-3 py-1.5 text-xs">{item.archived ? "Pulihkan" : "Arsipkan"}</button>{remove && <button type="button" onClick={() => remove(item)} className="secondary-button min-h-9 px-3 py-1.5 text-xs text-red-600 dark:text-red-300"><Trash2 size={14} /> Hapus</button>}</div></div>; })}</div>{visible.length === 0 && <p className="text-sm text-zinc-500">Tidak ada item pada filter ini.</p>}{filtered.length > 0 && <div className="flex flex-wrap items-center gap-2 text-xs text-zinc-500"><button type="button" disabled={page <= 1} onClick={() => setPage((value) => value - 1)} className="secondary-button min-h-8 px-2 py-1 disabled:opacity-40">Sebelumnya</button><span>Halaman {page} dari {totalPages} · {filtered.length} item</span><button type="button" disabled={page >= totalPages} onClick={() => setPage((value) => value + 1)} className="secondary-button min-h-8 px-2 py-1 disabled:opacity-40">Berikutnya</button></div>}</details>;
}

function QuizForm({ quiz, setQuiz, save, cancel, uploadQuestionImage, pending }: any) { const updateQuestion = (index: number, change: any) => { const questions = [...quiz.questions]; questions[index] = { ...questions[index], ...change }; setQuiz({ ...quiz, questions }); }; return <div className="space-y-4 rounded-xl bg-zinc-50 p-4 dark:bg-zinc-800/60"><div className="grid gap-4 md:grid-cols-2"><label className="block space-y-2 text-sm font-medium">Judul quiz/ujian<input className={inputClass} placeholder="Contoh: Quiz Bab 1" value={quiz.title} onChange={(event) => setQuiz({ ...quiz, title: event.target.value })} /></label>{quiz.kind !== undefined && <SelectField value={quiz.kind} onChange={(value) => setQuiz({ ...quiz, kind: value })} label="Jenis evaluasi" options={[{ value: "QUIZ", label: "Quiz" }, { value: "PRETEST", label: "Pretest" }, { value: "POSTTEST", label: "Posttest" }]} />}<label className="block space-y-2 text-sm font-medium">Passing score (%)<input type="number" min="0" max="100" className={inputClass} value={quiz.passingScore ?? 60} onChange={(event) => setQuiz({ ...quiz, passingScore: Number(event.target.value) })} /></label><label className="block space-y-2 text-sm font-medium">Waktu pengerjaan (menit)<input type="number" min="1" className={inputClass} placeholder="Kosong = tanpa timer" value={quiz.timeLimit ?? ""} onChange={(event) => setQuiz({ ...quiz, timeLimit: event.target.value ? Number(event.target.value) : "" })} /></label></div><AvailabilityFields value={quiz} setValue={setQuiz} includeDeadline /><div className="grid gap-3 rounded-xl border border-zinc-200 p-4 dark:border-zinc-700 md:grid-cols-2"><label className="flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={quiz.attemptLimited} onChange={(event) => setQuiz({ ...quiz, attemptLimited: event.target.checked })} /> Batasi jumlah attempt</label>{quiz.attemptLimited && <label className="block space-y-2 text-sm font-medium">Maksimal attempt (0 = ditutup)<input type="number" min="0" className={inputClass} value={quiz.attemptLimit} onChange={(event) => setQuiz({ ...quiz, attemptLimit: Number(event.target.value) })} /></label>}<p className="col-span-full text-xs text-zinc-500">Nonaktif = tak terbatas (-1) · aktif + 0 = mahasiswa tidak dapat mengerjakan.</p><SelectField value={quiz.timerMode || "INDEPENDENT"} onChange={(value) => setQuiz({ ...quiz, timerMode: value })} label="Mode timer" options={[{ value: "INDEPENDENT", label: "Independen dari deadline" }, { value: "SYNC_DEADLINE", label: "Serentak mengikuti deadline" }]} /><label className="block space-y-2 text-sm font-medium">Jumlah soal (kosong = semua)<input type="number" min="1" className={inputClass} value={quiz.questionCount ?? ""} onChange={(event) => setQuiz({ ...quiz, questionCount: event.target.value ? Number(event.target.value) : null })} /></label><label className="flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={Boolean(quiz.randomizeQuestions)} onChange={(event) => setQuiz({ ...quiz, randomizeQuestions: event.target.checked })} /> Acak urutan soal</label><label className="flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={Boolean(quiz.randomizeOptions)} onChange={(event) => setQuiz({ ...quiz, randomizeOptions: event.target.checked })} /> Acak urutan opsi</label><label className="flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={Boolean(quiz.showAnswers)} onChange={(event) => setQuiz({ ...quiz, showAnswers: event.target.checked })} /> Tampilkan jawaban setelah hasil dirilis</label></div><ResultReleaseFields quiz={quiz} setQuiz={setQuiz} />{quiz.questions.map((question: any, index: number) => <div key={index} className="space-y-3 rounded-xl border border-zinc-200 p-3 dark:border-zinc-700"><SelectField value={question.type || "MULTIPLE_CHOICE"} onChange={(value) => updateQuestion(index, { type: value, options: value === "ESSAY" ? [] : question.options?.length >= 2 ? question.options : ["", ""], correctIndex: value === "ESSAY" ? null : question.correctIndex ?? 0 })} label={`Tipe soal ${index + 1}`} options={[{ value: "MULTIPLE_CHOICE", label: "Pilihan ganda" }, { value: "ESSAY", label: "Essay" }]} /><label className="block space-y-2 text-sm font-medium">Pertanyaan {index + 1}<input className={inputClass} placeholder="Tulis pertanyaan" value={question.text} onChange={(event) => updateQuestion(index, { text: event.target.value })} /></label>{question.type !== "ESSAY" && <>{question.options.map((option: string, optionIndex: number) => <label key={optionIndex} className="flex items-center gap-2 text-sm"><input className={`${inputClass} flex-1`} aria-label={`Opsi ${String.fromCharCode(65 + optionIndex)}`} placeholder={`Teks opsi ${String.fromCharCode(65 + optionIndex)}`} value={option} onChange={(event) => { const options = [...question.options]; options[optionIndex] = event.target.value; updateQuestion(index, { options }); }} /><span>Jawaban benar</span><input aria-label={`Jawaban benar opsi ${String.fromCharCode(65 + optionIndex)}`} type="radio" checked={question.correctIndex === optionIndex} onChange={() => updateQuestion(index, { correctIndex: optionIndex })} /></label>)}<div className="flex flex-wrap gap-2"><button type="button" onClick={() => updateQuestion(index, { options: [...question.options, ""] })} className="secondary-button text-xs">Tambah opsi</button>{question.options.length > 2 && <button type="button" onClick={() => updateQuestion(index, { options: question.options.slice(0, -1), correctIndex: Math.min(question.correctIndex ?? 0, question.options.length - 2) })} className="secondary-button text-xs">Hapus opsi</button>}</div></>}{question.type === "ESSAY" && <p className="text-xs text-zinc-500">Jawaban essay diisi mahasiswa dan dinilai manual.</p>}<label className="block space-y-2 text-sm font-medium">Poin soal<input type="number" min="1" className={inputClass} value={question.points ?? 10} onChange={(event) => { const raw = event.target.value; const points = raw === "" ? "" : Math.min(100, Math.max(1, Number(raw) || 1)); updateQuestion(index, { points }); }} /></label><label className="block space-y-2 text-sm font-medium">URL gambar soal (opsional)<input className={inputClass} placeholder="https://..." value={question.imageUrl || ""} onChange={(event) => updateQuestion(index, { imageUrl: event.target.value })} /></label><label className="block space-y-2 text-sm font-medium">Upload gambar soal<input type="file" accept="image/jpeg,image/png,image/gif,image/webp" className="field p-2" onChange={(event) => { const file = event.target.files?.[0]; if (file) uploadQuestionImage(index, file); }} /><span className="block text-xs font-normal text-zinc-500">JPG, PNG, GIF, WEBP · maksimal 5 MB.</span></label>{question.imageUrl && <img src={mediaUrl(question.imageUrl)} alt={`Preview soal ${index + 1}`} className="max-h-40 rounded-lg object-contain" />}</div>)}<div className="flex flex-wrap gap-2"><button type="button" onClick={() => setQuiz({ ...quiz, questions: [...quiz.questions, newQuestion()] })} className="secondary-button"><Plus size={16} /> Tambah soal</button><FormButtons save={save} cancel={cancel} pending={pending} /></div></div>; }
function ResultReleaseFields({ quiz, setQuiz }: any) { return <div className="grid gap-3 rounded-xl border border-violet-200 bg-violet-50/50 p-4 dark:border-violet-900 dark:bg-violet-950/20"><SelectField value={quiz.resultReleaseMode || "AUTO"} onChange={(value) => setQuiz({ ...quiz, resultReleaseMode: value, resultReleaseAt: value === "SCHEDULED" ? quiz.resultReleaseAt || "" : "" })} label="Publikasi nilai" options={[{ value: "AUTO", label: "Langsung setelah selesai" }, { value: "HIDDEN", label: "Tersembunyi (dosen/admin saja)" }, { value: "MANUAL", label: "Manual oleh dosen/admin" }, { value: "SCHEDULED", label: "Terjadwal" }]} />{quiz.resultReleaseMode === "SCHEDULED" && <label className="block space-y-2 text-sm font-medium">Nilai dipublikasikan mulai<input type="datetime-local" className={inputClass} value={quiz.resultReleaseAt || ""} onChange={(event) => setQuiz({ ...quiz, resultReleaseAt: event.target.value })} /></label>}<p className="text-xs text-zinc-500">Langsung = mahasiswa melihat hasil setelah mengirim. Tersembunyi = hanya dosen/admin yang dapat melihat sampai dirilis.</p></div>; }
function QuizImportTools({ courseId, moduleId, onDone }: { courseId: string; moduleId: string; onDone: () => void }) { const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false); const { showFeedback } = useFeedback(); const downloadTemplate = async () => { try { const response = await api.get("/api/quizzes/template", { params: { moduleId }, responseType: "blob" }); const url = URL.createObjectURL(response.data); const link = document.createElement("a"); link.href = url; link.download = "template-soal.xlsx"; link.click(); URL.revokeObjectURL(url); } catch { showFeedback("Template Excel gagal diunduh.", "error"); } }; const importFile = async () => { if (!file) return; setBusy(true); try { const data = new FormData(); data.append("courseId", courseId); data.append("moduleId", moduleId); data.append("file", file); const response = await api.post("/api/quizzes/import", data); showFeedback(`${response.data.quizCount} quiz dan ${response.data.questionCount} soal berhasil dibuat.`); setFile(null); onDone(); } catch (error: any) { const details = error.response?.data?.errors?.join(" "); showFeedback(details || error.response?.data?.message || "Import gagal.", "error"); } finally { setBusy(false); } }; return <div className="space-y-3 rounded-xl border border-dashed border-violet-300 p-4 dark:border-violet-800"><div className="flex flex-wrap items-center gap-2"><button type="button" onClick={downloadTemplate} className="secondary-button"><FileUp size={16} /> Download template soal</button><label className="flex flex-wrap items-center gap-2 text-sm font-medium">File Excel<input type="file" accept=".xlsx,.xls" aria-label="File template Excel" onChange={(event) => setFile(event.target.files?.[0] || null)} className="max-w-full text-sm font-normal" /></label><button type="button" onClick={importFile} disabled={!file || busy} className="primary-button">{busy ? "Mengimpor..." : "Import soal"}</button></div><p className="text-xs text-zinc-500">Kolom options memakai delimiter <code>||</code>. Template menggunakan modul aktif.</p></div>; }
function ExamModuleDetail({ course, module, onBack, editingQuiz, setEditingQuiz, quiz, setQuiz, saveQuiz, uploadQuestionImage, pending, loadCourse, removeContent }: any) { const quizzes = module.quizzes || []; const publish = async (item: any) => { try { await api.patch(`/api/quizzes/${item.id}/result-release`, { resultReleaseMode: "MANUAL", publish: true }); await loadCourse(); } catch { } }; const reorderTo = async (sourceId: string, targetId: string) => { try { await reorderByDrag(quizzes, sourceId, targetId, async (id, direction) => { await api.patch(`/api/quizzes/${id}/reorder`, { direction }); }); await loadCourse(); } catch { } }; return <div className="mx-auto max-w-6xl space-y-7"><div className="flex flex-wrap items-center gap-2 text-xs font-medium text-zinc-500"><button type="button" onClick={onBack} className="hover:text-violet-600">Kelola Mata Kuliah</button><span>→</span><span>{course.title}</span><span>→</span><span>{module.title}</span></div><Header eyebrow={`${module.type} · ${course.title}`} title={module.title} back={onBack} backLabel="Kembali ke detail mata kuliah" /><section className="section-card"><p className="text-sm text-zinc-500">Modul {module.type} hanya berisi pengaturan ujian dan bank soal. Materi serta tugas tidak tersedia.</p></section><QuizImportTools courseId={course.id} moduleId={module.id} onDone={loadCourse} /><ContentSection title={`Bank soal ${module.type}`} icon={<ClipboardCheck size={18} />} items={quizzes} start={() => { const exam: any = newQuiz(module.type); delete exam.kind; setEditingQuiz("new"); setQuiz(exam); }} dragReorder={reorderTo} renderItem={(item: any) => <><p className="font-semibold">{item.title}</p><p className="text-xs text-zinc-500">{item.questions?.length || 0} soal · {item.attemptLimit === -1 ? "Tak terbatas" : `${item.attemptLimit} attempt`} · Nilai: {item.resultReleaseMode === "SCHEDULED" ? "Terjadwal" : item.resultReleaseMode === "MANUAL" ? item.resultPublishedAt ? "Sudah dipublikasikan" : "Manual" : "Tersembunyi"}</p>{item.resultReleaseMode === "MANUAL" && !item.resultPublishedAt && <button type="button" onClick={(event) => { event.stopPropagation(); publish(item); }} className="secondary-button mt-2 text-xs">Publikasikan hasil</button>}</>} edit={(item: any) => { const limit = item.attemptLimit ?? 1; setEditingQuiz(item.id); const editForm: any = { ...newQuiz(item.title), ...item, attemptLimited: limit !== -1, attemptLimit: limit < 0 ? 1 : limit, availableFrom: toLocalDateTime(item.availableFrom), availableUntil: toLocalDateTime(item.availableUntil), deadline: toLocalDateTime(item.deadline), resultReleaseAt: toLocalDateTime(item.resultReleaseAt), questions: (item.questions || []).map((question: any) => ({ ...question, options: parseOptions(question.options), imageUrl: question.imageUrl || "" })) }; delete editForm.kind; setQuiz(editForm); }} archive={async (item: any) => { await api.put(`/api/quizzes/${item.id}`, { archived: !item.archived }); await loadCourse(); }} remove={removeContent("quizzes")} form={editingQuiz && <QuizForm quiz={quiz} setQuiz={setQuiz} save={saveQuiz} cancel={() => setEditingQuiz(null)} uploadQuestionImage={uploadQuestionImage} pending={pending} />} /></div>; }
